import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

fn addTo(acc: Int64, x: Int64) -> Int64 { return acc + x }

pub fn main() effect io -> Result<(), AppError> {
    let fs = [1.5, 2.5, 4.0]
    let d = fs.iterator().fold(0.0, |acc, x| acc + x)
    if d == 8.0 { io.println("float-ok") } else { io.println("float-bad") }

    let cs = [Cell { n: 1 }, Cell { n: 2 }, Cell { n: 3 }]
    let t = cs.iterator().fold(0, |acc, c| acc + c.n)
    if t == 6 { io.println("gc-ok") } else { io.println("gc-bad") }

    let held = cs.iterator().any(|c| c.n > 2)
    if held { io.println("gc-any-ok") } else { io.println("gc-any-bad") }

    let k = 10
    let cap = [1, 2, 3].iterator().fold(0, |acc, x| acc + x * k)
    if cap == 60 { io.println("capture-ok") } else { io.println("capture-bad") }

    let f = addTo
    let ho = [1, 2, 3].iterator().fold(0, f)
    if ho == 6 { io.println("fnval-ok") } else { io.println("fnval-bad") }

    let blk = [1, 2, 3].iterator().any(|x| {
        let y = x * 2
        y > 4
    })
    if blk { io.println("block-ok") } else { io.println("block-bad") }

    let nested = 0
    for i in [1, 2] {
        nested = nested + [10, 20].iterator().fold(0, |acc, x| acc + x + i)
    }
    if nested == 66 { io.println("nested-ok") } else { io.println("nested-bad") }

    return Ok(())
}
